#include <iostream>
#include <string>
#include <vector>

int main()
{
    int cap{};
    int m{};
    std::cin >> cap >> m;

    std::vector<int> buf(static_cast<std::size_t>(cap), 0);
    int start{ 0 };
    int n{ 0 };

    for (int i = 0; i < m; ++i)
    {
        std::string cmd;
        std::cin >> cmd;

        if (cmd == "write")
        {
            int v{};
            std::cin >> v;
            buf[static_cast<std::size_t>((start + n) % cap)] = v;
            if (n == cap) { start = (start + 1) % cap; }
            else          { ++n; }
        }
        else if (cmd == "count")
        {
            std::cout << n << "\n";
        }
        else if (cmd == "dump")
        {
            if (n == 0)
            {
                std::cout << "empty\n";
                continue;
            }
            for (int k = 0; k < n; ++k)
            {
                std::cout << buf[static_cast<std::size_t>((start + k) % cap)]
                          << (k + 1 == n ? '\n' : ' ');
            }
        }
    }

    return 0;
}
